def test_k(k):
    # Try to find a counterexample for k
    # Try equal elements x = k/n
    for n in range(1, 100):
        x = k / n
        if x <= 1:
            S = [x] * n
            if not can_partition(S, k):
                return False, S
    # Try elements slightly different
